PROGRAM TankLevel
VAR_INPUT AutoEnable AT %I0.0 : BOOL; LevelLow AT %I0.1 : BOOL; LevelHigh AT %I0.2 : BOOL; PumpFault AT %I0.3 : BOOL; EStop AT %I0.4 : BOOL; Reset AT %I0.5 : BOOL; END_VAR
VAR_OUTPUT Pump AT %Q0.0 : BOOL; Alarm AT %Q0.1 : BOOL; END_VAR
Pump := AutoEnable AND LevelLow AND NOT PumpFault;
Alarm := PumpFault;
END_PROGRAM

PROGRAM TankLevel
VAR_INPUT AutoEnable AT %I0.0 : BOOL; LevelLow AT %I0.1 : BOOL; LevelHigh AT %I0.2 : BOOL; PumpFault AT %I0.3 : BOOL; EStop AT %I0.4 : BOOL; Reset AT %I0.5 : BOOL; END_VAR
VAR_OUTPUT Pump AT %Q0.0 : BOOL; Alarm AT %Q0.1 : BOOL; END_VAR
VAR PumpOn : BOOL := FALSE; Fault : BOOL := FALSE; END_VAR
Fault := EStop OR PumpFault;
IF Fault OR NOT AutoEnable OR LevelHigh THEN PumpOn := FALSE; ELSIF LevelLow THEN PumpOn := TRUE; END_IF;
Pump := PumpOn AND AutoEnable AND NOT Fault;
Alarm := Fault;
END_PROGRAM

PROGRAM TankLevel
VAR_INPUT AutoEnable AT %I0.0 : BOOL; LevelLow AT %I0.1 : BOOL; LevelHigh AT %I0.2 : BOOL; PumpFault AT %I0.3 : BOOL; EStop AT %I0.4 : BOOL; Reset AT %I0.5 : BOOL; END_VAR
VAR_OUTPUT Pump AT %Q0.0 : BOOL; Alarm AT %Q0.1 : BOOL; END_VAR
VAR PumpOn : BOOL := FALSE; Fault : BOOL := FALSE; END_VAR
IF EStop OR PumpFault THEN Fault := TRUE; END_IF;
IF Fault OR NOT AutoEnable OR LevelHigh THEN PumpOn := FALSE; ELSIF LevelLow THEN PumpOn := TRUE; END_IF;
Pump := PumpOn AND AutoEnable AND NOT Fault;
Alarm := Fault;
END_PROGRAM
